// Material's built-in Mermaid integration calls mermaid.initialize() without
// `securityLevel`, which defaults to "strict" and silently disables node
// `click` bindings. All diagram content here is generated by our own
// scripts/generate_docs.py (never user-supplied), so "loose" is safe.
document$.subscribe(() => {
  if (typeof mermaid !== "undefined") {
    mermaid.initialize({ startOnLoad: false, securityLevel: "loose" });
  }
});
